/**
 * Kokoro-82M voices, generated by the local TTS server in `tts-server/`.
 * Saved voice names carry a prefix so they can't clash with browser voices.
 */

export const TTS_SERVER_URL = 'http://127.0.0.1:5005';
const VOICE_PREFIX = 'kokoro:';

export const KOKORO_VOICES = Object.freeze([
  { id: 'af_heart', label: 'Heart (US female, best)' },
  { id: 'af_bella', label: 'Bella (US female)' },
  { id: 'af_nicole', label: 'Nicole (US female, soft)' },
  { id: 'af_aoede', label: 'Aoede (US female)' },
  { id: 'af_kore', label: 'Kore (US female)' },
  { id: 'af_sarah', label: 'Sarah (US female)' },
  { id: 'af_nova', label: 'Nova (US female)' },
  { id: 'af_sky', label: 'Sky (US female)' },
  { id: 'bf_emma', label: 'Emma (UK female)' },
  { id: 'bf_isabella', label: 'Isabella (UK female)' },
  { id: 'am_michael', label: 'Michael (US male)' },
  { id: 'am_fenrir', label: 'Fenrir (US male)' },
  { id: 'am_puck', label: 'Puck (US male)' },
  { id: 'bm_george', label: 'George (UK male)' },
  { id: 'bm_fable', label: 'Fable (UK male)' },
]);

export function isKokoroVoice(voiceName) {
  return voiceName.startsWith(VOICE_PREFIX);
}

export function toKokoroVoiceName(id) {
  return VOICE_PREFIX + id;
}

export function kokoroVoiceId(voiceName) {
  return voiceName.slice(VOICE_PREFIX.length);
}

/** @returns {Promise<{ ready: boolean, message: string }>} */
export async function checkTtsServer() {
  try {
    const response = await fetch(`${TTS_SERVER_URL}/health`);
    return await response.json();
  } catch {
    return { ready: false, message: 'Kokoro server is not running. Run tts-server\\start.bat' };
  }
}

/** @returns {Promise<Blob>} WAV audio. */
export async function fetchSpeech(text, voice) {
  let response;
  try {
    response = await fetch(`${TTS_SERVER_URL}/tts`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text, voice }),
    });
  } catch {
    throw new Error(`Kokoro server is not running at ${TTS_SERVER_URL}.`);
  }
  if (!response.ok) {
    const { error } = await response.json().catch(() => ({}));
    throw new Error(`Kokoro error (HTTP ${response.status}): ${error ?? response.statusText}`);
  }
  return response.blob();
}
